586	// GetBill 返回指定账期的账单；尚未出账返回 ErrBillNotFound。
587	func (s *Service) GetBill(accountID string, period Month) (Bill, error) {
588		if accountID == "" {
589			return Bill{}, invalidf("account id is empty")
590		}
591		s.mu.Lock()
592		defer s.mu.Unlock()
593		acc, ok := s.accounts[accountID]
594		if !ok {
595			return Bill{}, ErrAccountNotFound
596		}
597		rec, ok := acc.bills[period]
598		if !ok {
599			return Bill{}, ErrBillNotFound
600		}
601		return rec.bill, nil
602	}
