370		if _, err := s.CreateBill("a", jan(2026)); err != nil {
371			t.Fatal(err)
372		}
373	
374		// p1 首次支付 400：余额 600，未付清。
375		r1, err := s.RecordPayment("a", "p1", jan(2026), 400)
376		if err != nil || !r1.Registered || r1.BillBalance != 600 || r1.Settled {
377			t.Fatalf("p1 first: %+v %v", r1, err)
378		}
379		// p2 支付剩余 600：账单当前余额 0，已付清。
380		r2, err := s.RecordPayment("a", "p2", jan(2026), 600)
381		if err != nil || !r2.Registered || r2.BillBalance != 0 || !r2.Settled {
382			t.Fatalf("p2: %+v %v", r2, err)
383		}
384	
385		// 原样重报 p1：不再登记，返回首次登记时的历史结果。
386		r1b, err := s.RecordPayment("a", "p1", jan(2026), 400)
387		if err != nil {
388			t.Fatalf("p1 replay: %v", err)
389		}
390		if r1b.Registered {
391			t.Fatalf("p1 replay should not register again: %+v", r1b)
392		}
393		if r1b.Payment.Amount != 400 || r1b.Payment.Period != jan(2026) || r1b.Payment.PaymentID != "p1" {
394			t.Fatalf("p1 replay payment content: %+v", r1b.Payment)
395		}
396		if r1b.BillBalance != 600 || r1b.Settled {
397			t.Fatalf("p1 replay historical result: balance=%d settled=%v, want 600/false", r1b.BillBalance, r1b.Settled)
398		}
399		// 原样重报 p2：历史结果为余额 0、已付清。
400		r2b, err := s.RecordPayment("a", "p2", jan(2026), 600)
401		if err != nil || r2b.Registered || r2b.BillBalance != 0 || !r2b.Settled {
402			t.Fatalf("p2 replay: %+v %v", r2b, err)
403		}
404	
405		// 重报不再次增加已付金额；账单查询仍显示当前状态：已付 1000、余额 0、已付清。
406		b, err := s.GetBill("a", jan(2026))
407		if err != nil {
408			t.Fatal(err)
409		}
410		if b.Paid != 1000 || b.Balance != 0 || !b.Settled {
411			t.Fatalf("bill current state after replays: paid=%d balance=%d settled=%v", b.Paid, b.Balance, b.Settled)
412		}
413		if b.TotalUsage != 0 || b.TotalDue != 1000 || b.Tax != 0 {
414			t.Fatalf("bill amounts changed: %+v", b)
415		}
416		st, err := s.Status("a")
417		if err != nil {
418			t.Fatal(err)
419		}
420		if len(st.Bills) != 1 || st.Bills[0].Paid != 1000 || st.Bills[0].Balance != 0 || !st.Bills[0].Settled {
421			t.Fatalf("status bill summary: %+v", st.Bills)
422		}
423	
424		// 即使已过截止时刻，账户已因结清恢复，不能因旧付款结果显示未付清而重新停用。
425		clk.t = utc(2026, 2, 8, 0, 0)
426		st, _ = s.Status("a")
427		if st.Suspended {
428			t.Fatalf("account re-suspended by historical unpaid replay: %+v", st)
429		}
430		if _, err := s.RecordPayment("a", "p1", jan(2026), 400); err != nil {
431			t.Fatalf("p1 replay after due: %v", err)
432		}
433		st, _ = s.Status("a")
434		if st.Suspended {
435			t.Fatalf("suspended after replay post-due: %+v", st)
436		}
437	}
